//! M1-10: 3D LUT sampling against OpenColorIO tetrahedral vectors on our own synthetic .cube files
//! (generated by tools/vectors/lut_vectors.py), plus properties of the interpolation.

use serde_json::Value;
use std::path::PathBuf;
use ym_color::cube;
use ym_color::cube::{CubeError, MAX_3D_SIZE};
use ym_color::lut::{Lut, Lut3d, LutError};

fn data_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/data/lut")
}

fn load(name: &str) -> Lut {
    let text = std::fs::read_to_string(data_dir().join(name)).unwrap();
    cube::parse_lut(&text).unwrap_or_else(|e| panic!("{name}: {e}"))
}

fn vec3(v: &Value) -> [f64; 3] {
    let a = v.as_array().unwrap();
    [
        a[0].as_f64().unwrap(),
        a[1].as_f64().unwrap(),
        a[2].as_f64().unwrap(),
    ]
}

/// One code value at 10 bits, as a fraction of full scale.
const ONE_CODE_VALUE_10_BIT: f64 = 1.0 / 1023.0;

#[test]
fn matches_opencolorio_tetrahedral_vectors() {
    let doc: Value = serde_json::from_str(
        &std::fs::read_to_string(data_dir().join("lut_vectors.json")).unwrap(),
    )
    .unwrap();
    assert_eq!(doc["interpolation"], "tetrahedral");
    println!("vectors from OpenColorIO {}", doc["ocio_version"]);
    let mut overall = 0.0_f64;
    let mut total = 0;
    for case in doc["cases"].as_array().unwrap() {
        let name = case["file"].as_str().unwrap();
        let lut = load(name);
        let inputs = case["inputs"].as_array().unwrap();
        let outputs = case["outputs"].as_array().unwrap();
        assert_eq!(inputs.len(), outputs.len());
        let mut worst = 0.0_f64;
        for (i, o) in inputs.iter().zip(outputs) {
            let (i, o) = (vec3(i), vec3(o));
            let got = lut.sample(i);
            for c in 0..3 {
                worst = worst.max((got[c] - o[c]).abs());
            }
        }
        println!(
            "{name:20} {} points, max |ours - OCIO| = {worst:.3e} ({:.4} code values at 10 bits)",
            inputs.len(),
            worst / ONE_CODE_VALUE_10_BIT
        );
        overall = overall.max(worst);
        total += inputs.len();
        // Gate: at most 1 code value at 10 bits. In practice OCIO's float32 maths is the only difference.
        assert!(worst <= ONE_CODE_VALUE_10_BIT, "{name}: {worst:e}");
        assert!(
            worst < 5e-6,
            "{name}: {worst:e} is more than float32 rounding explains"
        );
    }
    println!(
        "LUT parity: {total} points, max error {overall:.3e} = {:.4} code values at 10 bits",
        overall / ONE_CODE_VALUE_10_BIT
    );
}

#[test]
fn trilinear_would_fail_the_same_vectors() {
    // The warp cubes are non-linear enough that trilinear and tetrahedral differ by far more than the
    // tolerance, so the parity test above really pins the interpolation method.
    let doc: Value = serde_json::from_str(
        &std::fs::read_to_string(data_dir().join("lut_vectors.json")).unwrap(),
    )
    .unwrap();
    for case in doc["cases"].as_array().unwrap() {
        let name = case["file"].as_str().unwrap();
        if name != "warp_17.cube" && name != "ripple_33.cube" {
            continue;
        }
        let lut = load(name);
        let mut worst = 0.0_f64;
        for (i, o) in case["inputs"]
            .as_array()
            .unwrap()
            .iter()
            .zip(case["outputs"].as_array().unwrap())
        {
            let (i, o) = (vec3(i), vec3(o));
            let got = lut.cube.sample_trilinear(i);
            for c in 0..3 {
                worst = worst.max((got[c] - o[c]).abs());
            }
        }
        println!(
            "{name}: trilinear vs OCIO tetrahedral max diff {worst:e} ({:.2} code values at 10 bits)",
            worst / ONE_CODE_VALUE_10_BIT
        );
        // warp_17 must fail the 1-code-value gate if trilinear were used; ripple_33 (finer grid) still differs measurably.
        let bar = if name == "warp_17.cube" {
            ONE_CODE_VALUE_10_BIT
        } else {
            1.0e-4
        };
        assert!(
            worst > bar,
            "{name}: trilinear is too close to tetrahedral to discriminate ({worst:e})"
        );
    }
}

#[test]
fn identity_cube_is_the_identity_everywhere() {
    let lut = load("identity_9.cube");
    for k in 0..2000 {
        let t = f64::from(k) / 1999.0;
        let rgb = [t, 1.0 - t, (t * 7.0).fract()];
        let out = lut.sample(rgb);
        for c in 0..3 {
            assert!((out[c] - rgb[c]).abs() < 1e-7, "{rgb:?} -> {out:?}");
        }
    }
}

#[test]
fn exact_at_grid_nodes_and_continuous_across_cell_faces() {
    let lut = load("warp_17.cube");
    let cube = &lut.cube;
    let n = cube.size();
    for r in 0..n {
        for g in (0..n).step_by(3) {
            for b in (0..n).step_by(5) {
                let at = cube.entry(r, g, b).unwrap();
                let x = [
                    r as f64 / (n - 1) as f64,
                    g as f64 / (n - 1) as f64,
                    b as f64 / (n - 1) as f64,
                ];
                let got = cube.sample(x);
                for c in 0..3 {
                    assert!((got[c] - at[c]).abs() < 1e-12);
                }
            }
        }
    }
    // Continuity across a face: sample either side of an interior grid plane and on it.
    let mut worst = 0.0_f64;
    for k in 0..200 {
        let (y, z) = (0.013 + 0.0049 * f64::from(k), 0.97 - 0.0043 * f64::from(k));
        for plane in [4.0 / 16.0, 9.0 / 16.0] {
            let below = cube.sample([plane - 1e-9, y, z]);
            let above = cube.sample([plane + 1e-9, y, z]);
            for c in 0..3 {
                worst = worst.max((below[c] - above[c]).abs());
            }
        }
    }
    assert!(worst < 1e-7, "{worst:e}");
}

#[test]
fn inputs_are_clamped_to_the_domain() {
    let lut = load("domain_9.cube");
    let lo = lut.cube.domain_min();
    let hi = lut.cube.domain_max();
    assert_eq!(lo, [-0.1, -0.2, 0.0]);
    assert_eq!(hi, [1.5, 1.2, 2.0]);
    assert_eq!(lut.sample([-5.0, -5.0, -5.0]), lut.sample(lo));
    assert_eq!(lut.sample([9.0, 9.0, 9.0]), lut.sample(hi));
    assert_eq!(
        lut.sample([-5.0, 0.5, 9.0]),
        lut.sample([lo[0], 0.5, hi[2]])
    );
    // NaN is treated as the domain minimum rather than propagating.
    assert_eq!(
        lut.sample([f64::NAN, 0.5, 1.0]),
        lut.sample([lo[0], 0.5, 1.0])
    );
    assert!(
        lut.sample([f64::INFINITY, f64::NEG_INFINITY, 0.0])
            .iter()
            .all(|v| v.is_finite())
    );
}

#[test]
fn shaper_is_applied_before_the_cube() {
    let lut = load("shaper_3d_9.cube");
    let shaper = lut.shaper.as_ref().expect("1D shaper");
    assert_eq!(shaper.size(), 64);
    assert_eq!(shaper.domain_min(), [-0.05; 3]);
    assert_eq!(shaper.domain_max(), [1.1; 3]);
    assert_eq!(lut.cube.size(), 9);
    let x = [0.3, 0.6, 0.9];
    assert_eq!(lut.sample(x), lut.cube.sample(shaper.sample(x)));
    // The shaper is not the identity, so skipping it changes the result.
    assert!(lut.cube.sample(x)[0] != lut.sample(x)[0]);
}

#[test]
fn tetrahedral_is_exact_for_linear_functions() {
    // Both interpolations reproduce an affine map exactly; a quick check of the six-case split.
    let f = |c: [f64; 3]| {
        [
            0.3 * c[0] + 0.1 * c[1] - 0.2 * c[2] + 0.05,
            c[0] * 0.5 + 0.5 * c[2],
            1.0 - c[1] * 0.9,
        ]
    };
    let lut = Lut3d::bake(6, [0.0; 3], [1.0; 3], f).unwrap();
    let mut seed = 0x1234_5678_u64;
    let mut next = || {
        seed = seed
            .wrapping_mul(6364136223846793005)
            .wrapping_add(1442695040888963407);
        ((seed >> 11) as f64) / ((1_u64 << 53) as f64)
    };
    for _ in 0..5000 {
        let p = [next(), next(), next()];
        let got = lut.sample(p);
        let want = f(p);
        for c in 0..3 {
            assert!((got[c] - want[c]).abs() < 1e-12, "{p:?}");
        }
    }
}

#[test]
fn tetrahedral_is_monotone_for_a_monotone_lut() {
    // A LUT that is monotone on its grid stays monotone along each axis and along the diagonal.
    let lut = Lut3d::bake(9, [0.0; 3], [1.0; 3], |c| {
        [
            c[0].powf(0.6),
            c[1].powf(1.7),
            0.5 * c[2] + 0.5 * c[2] * c[2],
        ]
    })
    .unwrap();
    let mut prev = lut.sample([0.0; 3]);
    for k in 1..=4000 {
        let t = f64::from(k) / 4000.0;
        let cur = lut.sample([t; 3]);
        for c in 0..3 {
            assert!(cur[c] >= prev[c] - 1e-15);
        }
        prev = cur;
    }
}

#[test]
fn written_cubes_parse_back_to_identical_samples() {
    let lut = load("ripple_33.cube");
    let text = lut.cube.to_cube_string("again");
    let again = cube::parse_lut(&text).unwrap();
    assert_eq!(again.cube, lut.cube);
    for p in [[0.12, 0.8, 0.4], [0.5, 0.5, 0.5], [1.0, 0.0, 0.3]] {
        assert_eq!(again.sample(p), lut.sample(p));
    }
}

#[test]
fn texture_layouts_are_rgba_red_fastest() {
    let lut = Lut3d::bake(3, [0.0; 3], [1.0; 3], |c| c).unwrap();
    let rgba = lut.to_rgba_f32();
    assert_eq!(rgba.len(), 27 * 4);
    // Texel 1 is (r = 1, g = 0, b = 0) at the middle red grid point 0.5.
    assert_eq!(&rgba[4..8], &[0.5, 0.0, 0.0, 1.0]);
    // Texel 3 steps green; texel 9 steps blue.
    assert_eq!(&rgba[12..16], &[0.0, 0.5, 0.0, 1.0]);
    assert_eq!(&rgba[36..40], &[0.0, 0.0, 0.5, 1.0]);
}

#[test]
fn baking_is_bounded_by_the_largest_cube_file() {
    // A size is checked before anything is allocated: no overflow in size^3, no giant Vec.
    for size in [MAX_3D_SIZE + 1, 1000, 1 << 22, usize::MAX] {
        assert_eq!(
            Lut3d::bake(size, [0.0; 3], [1.0; 3], |c| c).unwrap_err(),
            LutError::TooLarge {
                size,
                max: MAX_3D_SIZE
            },
            "size {size}"
        );
        assert!(Lut3d::identity(size).is_err());
    }
    // The limit itself bakes (129 points is the largest cube file the parser accepts).
    let big = Lut3d::identity(MAX_3D_SIZE).unwrap();
    assert_eq!(big.data().len(), MAX_3D_SIZE.pow(3));
    assert!(matches!(Lut3d::identity(1), Err(LutError::TooSmall(1))));
}

#[test]
fn a_domain_whose_width_overflows_is_rejected() {
    // Finite ends but an infinite width would make the normalised position NaN.
    let data = vec![[0.0; 3]; 8];
    assert_eq!(
        Lut3d::new(2, [-1e308; 3], [1e308; 3], data.clone()),
        Err(LutError::BadDomain { channel: 0 })
    );
    assert!(Lut3d::bake(2, [0.0, -1e308, 0.0], [1.0, 1e308, 1.0], |c| c).is_err());
    let text = "DOMAIN_MIN -1e308 -1e308 -1e308\nDOMAIN_MAX 1e308 1e308 1e308\nLUT_3D_SIZE 2\n"
        .to_string()
        + &"0 0 0\n".repeat(8);
    assert_eq!(cube::parse(&text), Err(CubeError::BadDomain));
    // A wide but finite domain samples without NaN, even for infinite input.
    let wide = Lut3d::new(2, [-1e300; 3], [1e300; 3], data).unwrap();
    for p in [
        [f64::INFINITY; 3],
        [f64::NEG_INFINITY; 3],
        [f64::NAN; 3],
        [0.0; 3],
    ] {
        assert!(wide.sample(p).iter().all(|v| v.is_finite()), "{p:?}");
    }
}
